INSERT INTO `tag` (`name`, `status`) SELECT 'Hydroponics', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Hydroponics') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Sustainability', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Sustainability') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'WSQ') x);

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'strawberry-indoor-hydroponics-farm-singapore-2026');

